style.css:
/* =========================================================
   GARMIN CONNECT DARK GLASS THEME
   Built for: connect.garmin.com
   Vibe: dark dashboard, neon fitness cave, less office printer
   ========================================================= */

/* 
   MAIN COLORS
   Change these if you want a different flavor.
   Blue = Garmin/fitness tech vibe.
*/
:root {
  --gc-bg: #0b1020;
  --gc-panel: rgba(20, 28, 48, 0.82);
  --gc-panel-solid: #141c30;
  --gc-card: rgba(255, 255, 255, 0.08);
  --gc-card-hover: rgba(255, 255, 255, 0.13);
  --gc-text: #f4f7fb;
  --gc-muted: #9aa8bd;
  --gc-blue: #22c8ff;
  --gc-green: #2ef2a3;
  --gc-orange: #ff9f43;
  --gc-purple: #b86cff;
  --gc-border: rgba(255, 255, 255, 0.16);
  --gc-shadow: 0 18px 45px rgba(0, 0, 0, 0.35);
}

/* 
   PAGE BACKGROUND
   Gives the whole Garmin page a darker premium dashboard look.
*/
html,
body {
  background:
    radial-gradient(circle at top left, rgba(34, 200, 255, 0.22), transparent 32%),
    radial-gradient(circle at top right, rgba(184, 108, 255, 0.18), transparent 30%),
    linear-gradient(135deg, #070b14 0%, #101827 45%, #08111f 100%) !important;
  color: var(--gc-text) !important;
}

/* 
   MAIN CONTENT AREA
   Softens the white background and makes it feel like a modern app.
*/
main,
[class*="page"],
[class*="content"],
[class*="dashboard"],
[class*="main"] {
  background: transparent !important;
  color: var(--gc-text) !important;
}

/* 
   LEFT SIDEBAR
   Turns the navigation into a sleek dark command center.
*/
nav,
aside,
[class*="sidebar"],
[class*="SideBar"],
[class*="navigation"] {
  background: rgba(5, 8, 15, 0.92) !important;
  backdrop-filter: blur(18px) !important;
  border-right: 1px solid var(--gc-border) !important;
  box-shadow: 10px 0 30px rgba(0, 0, 0, 0.35) !important;
}

/* Sidebar text and icons */
nav *,
aside *,
[class*="sidebar"] * {
  color: var(--gc-text) !important;
}

/* Sidebar hover effect */
nav a:hover,
aside a:hover,
[class*="sidebar"] a:hover,
[class*="menu"] a:hover {
  background: rgba(34, 200, 255, 0.14) !important;
  color: #ffffff !important;
  border-radius: 14px !important;
  transition: all 0.2s ease !important;
}

/* 
   TOP BAR
   Makes the header glassy instead of plain white.
*/
header,
[class*="header"],
[class*="topbar"],
[class*="TopBar"] {
  background: rgba(8, 13, 24, 0.84) !important;
  backdrop-filter: blur(16px) !important;
  border-bottom: 1px solid var(--gc-border) !important;
  color: var(--gc-text) !important;
}

/* 
   DASHBOARD CARDS
   This is the money section. Cards become glass panels.
*/
[class*="card"],
[class*="Card"],
[class*="tile"],
[class*="Tile"],
[class*="widget"],
[class*="Widget"],
[class*="panel"],
[class*="Panel"] {
  background: var(--gc-card) !important;
  color: var(--gc-text) !important;
  border: 1px solid var(--gc-border) !important;
  border-radius: 22px !important;
  box-shadow: var(--gc-shadow) !important;
  backdrop-filter: blur(16px) !important;
  overflow: hidden !important;
  transition: transform 0.18s ease, box-shadow 0.18s ease, background 0.18s ease !important;
}

/* Card hover: little gym pump effect */
[class*="card"]:hover,
[class*="Card"]:hover,
[class*="tile"]:hover,
[class*="Tile"]:hover,
[class*="widget"]:hover,
[class*="Widget"]:hover {
  background: var(--gc-card-hover) !important;
  transform: translateY(-3px) !important;
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.48) !important;
}

/* 
   CARD HEADINGS
   Makes titles pop without screaming.
*/
h1,
h2,
h3,
h4,
[class*="title"],
[class*="Title"],
[class*="heading"],
[class*="Heading"] {
  color: #ffffff !important;
  letter-spacing: -0.02em !important;
}

/* Section headings like "In Focus" and "Today's Activity" */
h1,
h2 {
  font-weight: 800 !important;
  text-shadow: 0 0 24px rgba(34, 200, 255, 0.22) !important;
}

/* 
   BODY TEXT
   Keeps smaller text readable on dark mode.
*/
p,
span,
div,
td,
th,
label {
  color: var(--gc-text) !important;
}

/* Muted helper text */
small,
[class*="subtitle"],
[class*="Subtitle"],
[class*="description"],
[class*="Description"],
[class*="secondary"],
[class*="Secondary"] {
  color: var(--gc-muted) !important;
}

/* 
   LINKS AND BUTTONS
   Brings in the neon Garmin cockpit feeling.
*/
a {
  color: var(--gc-blue) !important;
}

button,
[role="button"],
input[type="button"],
input[type="submit"] {
  background: linear-gradient(135deg, var(--gc-blue), var(--gc-purple)) !important;
  color: #ffffff !important;
  border: none !important;
  border-radius: 999px !important;
  box-shadow: 0 8px 22px rgba(34, 200, 255, 0.28) !important;
  font-weight: 700 !important;
  transition: all 0.18s ease !important;
}

button:hover,
[role="button"]:hover {
  transform: translateY(-2px) !important;
  filter: brightness(1.12) !important;
}

/* 
   PROGRESS BARS
   Makes nutrition/activity bars look sharper.
*/
progress,
[class*="progress"],
[class*="Progress"],
[class*="bar"],
[class*="Bar"] {
  border-radius: 999px !important;
  overflow: hidden !important;
}

/* 
   INPUTS / SEARCH BOXES
   Dark glass search instead of ghost-white sadness.
*/
input,
textarea,
select {
  background: rgba(255, 255, 255, 0.08) !important;
  color: var(--gc-text) !important;
  border: 1px solid var(--gc-border) !important;
  border-radius: 14px !important;
}

input::placeholder,
textarea::placeholder {
  color: var(--gc-muted) !important;
}

/* 
   TABLES AND REPORT AREAS
   Helpful for Garmin reports pages.
*/
table {
  background: rgba(255, 255, 255, 0.05) !important;
  border-radius: 18px !important;
  overflow: hidden !important;
}

th {
  background: rgba(34, 200, 255, 0.12) !important;
  color: #ffffff !important;
}

td {
  border-color: rgba(255, 255, 255, 0.09) !important;
}

/* 
   SCROLLBAR
   Because default scrollbars look like leftover cafeteria trays.
*/
::-webkit-scrollbar {
  width: 12px !important;
  height: 12px !important;
}

::-webkit-scrollbar-track {
  background: #080d18 !important;
}

::-webkit-scrollbar-thumb {
  background: linear-gradient(var(--gc-blue), var(--gc-purple)) !important;
  border-radius: 999px !important;
  border: 3px solid #080d18 !important;
}

::-webkit-scrollbar-thumb:hover {
  background: linear-gradient(var(--gc-green), var(--gc-blue)) !important;
}

/* 
   IMAGES / AVATARS
   Gives profile images a cleaner premium ring.
*/
img {
  border-radius: 12px;
}

img[alt*="profile"],
[class*="avatar"] img,
[class*="Avatar"] img {
  border: 2px solid rgba(34, 200, 255, 0.65) !important;
  box-shadow: 0 0 18px rgba(34, 200, 255, 0.35) !important;
}

/* 
   WHITE BOX FIX
   Garmin sometimes hides white backgrounds deep inside random containers.
   This catches the stubborn little gremlins.
*/
[style*="background-color: rgb(255, 255, 255)"],
[style*="background: rgb(255, 255, 255)"],
[style*="background-color:#fff"],
[style*="background:#fff"],
[style*="background-color: white"],
[style*="background: white"] {
  background: var(--gc-card) !important;
  color: var(--gc-text) !important;
}

/* 
   CARD LABEL BADGES
   Makes little labels like WORKOUT feel cleaner.
*/
[class*="badge"],
[class*="Badge"],
[class*="label"],
[class*="Label"] {
  background: rgba(34, 200, 255, 0.16) !important;
  color: #dff8ff !important;
  border: 1px solid rgba(34, 200, 255, 0.28) !important;
  border-radius: 999px !important;
  font-weight: 700 !important;
}

/* 
   OPTIONAL: MAKE EVERYTHING A LITTLE ROOMIER
   Comment this section out if Garmin starts looking too chunky.
*/
[class*="card"],
[class*="Card"],
[class*="tile"],
[class*="Tile"],
[class*="widget"],
[class*="Widget"] {
  padding: 1.05rem !important;
}

/* 
   OPTIONAL: HIDE SOME AD/UPSELL STYLE AREAS
   If this hides something useful, delete this block.
*/
[class*="premium"],
[class*="Premium"],
[class*="upsell"],
[class*="Upsell"] {
  opacity: 0.65 !important;
}
